#ifndef LORA_HARDWARE_SUBMODULE_H
#define LORA_HARDWARE_SUBMODULE_H

#include "ns3/nstime.h"
#include "../lora-physics-parameters.h"
#include "../lora-distribution-sampler.h"
#include <map>

namespace ns3 {

/**
 * @brief Realistic timing and RSSI observation data generated by the receiver hardware
 */
struct TimestampObservation {
    uint32_t nodeId;
    uint32_t gatewayId;
    double trueArrivalTimeNs;
    double measuredArrivalTimeNs;
    double trueRssiDbm;
    double measuredRssiDbm;
    double snrDb;
    uint8_t spreadingFactor;
    uint8_t relayHops;
    bool captureOccurred;
    double cfoHz;           // Per-gateway Carrier Frequency Offset (CFO)
    double phaseNoiseRad;   // Phase noise at time of packet arrival
};

/**
 * @brief Simulates node and gateway hardware imperfections
 * Models transmitter power accuracy, gateway sensitivity variations,
 * RSSI hardware bias & quantization, CFO, phase noise, and GPS disciplining timestamp errors.
 */
class HardwareSubmodule {
public:
    HardwareSubmodule(const HardwareParams& params,
                       LoRaDistributionSampler& sampler);
    
    // Apply TX power variation - call at transmitter
    double ApplyTxPowerVariation(double nominalTxPowerDbm, 
                                  uint32_t nodeId);
    
    // Apply RX sensitivity variation - affects SNR threshold
    double ApplyRxSensitivityVariation(double nominalSensitivityDbm,
                                        uint32_t gatewayId);
    
    // Generate timestamp observation with realistic errors
    TimestampObservation GenerateTimestampObservation(
        uint32_t nodeId, uint32_t gatewayId,
        Time trueArrival, double trueRssiDbm, double snrDb,
        uint8_t sf, uint8_t relayHops);
    
    // Feature 6: Temperature-dependent CFO computation
    double ComputeTemperatureCFO(double temperatureCelsius, 
                                  const TemperatureCfoParams& params);
    
    // Apply RSSI quantization and hardware variation
    double ApplyRSSIErrors(double trueRssiDbm, uint32_t gatewayId);

    // Reset gateway timestamp jitter distribution for Fine Timestamp mode
    void ResetGatewayJitter(const HardwareParams& params);

private:
    const HardwareParams& m_params;
    LoRaDistributionSampler& m_sampler;
    
    // Per-gateway persistent offsets (sampled once at simulation start)
    std::map<uint32_t, double> m_gatewayTimestampJitter;
    std::map<uint32_t, double> m_gatewayRssiOffset;
    std::map<uint32_t, double> m_gatewaySensitivityOffset;
    std::map<uint32_t, double> m_gatewayCFO;
    
    // Per-node persistent TX power offsets
    std::map<uint32_t, double> m_nodeTxPowerOffset;
    
    void InitializeGateway(uint32_t gatewayId);
    void InitializeNode(uint32_t nodeId);
};

} // namespace ns3

#endif // LORA_HARDWARE_SUBMODULE_H
